// Simple top-down asteroid dodge game
// Canvas element with id="game" must exist in the HTML.

(() => {
  const canvas = document.getElementById("game");
  if (!canvas) {
    console.error("Canvas with id 'game' not found");
    return;
  }
  const ctx = canvas.getContext("2d");
  // Set canvas size to fill its container or default size
  canvas.width = canvas.clientWidth || 800;
  canvas.height = canvas.clientHeight || 600;

  // Game constants
  const SHIP_SIZE = 30; // side length of triangle ship
  const SHIP_SPEED = 4;
  const ASTEROID_MIN_SPEED = 2;
  const ASTEROID_MAX_SPEED = 5;
  const ASTEROID_SPAWN_INTERVAL = 1500; // ms
  const FUEL_SPAWN_INTERVAL = 5000; // ms
  const FUEL_SIZE = 15;
  const FUEL_AMOUNT = 30; // fuel added per pickup
  const FUEL_DECREASE_RATE = 0.02; // per frame

  // Input handling
  const keys = {};
  window.addEventListener("keydown", e => (keys[e.key] = true));
  window.addEventListener("keyup", e => (keys[e.key] = false));

  // Game objects
  const ship = {
    x: canvas.width / 2,
    y: canvas.height - SHIP_SIZE * 2,
    size: SHIP_SIZE,
    fuel: 100,
    alive: true,
  };

  const asteroids = [];
  const fuels = [];

  let lastAsteroidTime = 0;
  let lastFuelTime = 0;
  let score = 0;

  function spawnAsteroid() {
    const radius = Math.random() * 15 + 10;
    const x = Math.random() * (canvas.width - radius * 2) + radius;
    const speed = Math.random() * (ASTEROID_MAX_SPEED - ASTEROID_MIN_SPEED) + ASTEROID_MIN_SPEED;
    asteroids.push({ x, y: -radius, radius, speed });
  }

  function spawnFuel() {
    const x = Math.random() * (canvas.width - FUEL_SIZE) + FUEL_SIZE / 2;
    const y = -FUEL_SIZE;
    const speed = 2;
    fuels.push({ x, y, size: FUEL_SIZE, speed });
  }

  function update(delta) {
    if (!ship.alive) return;
    // Move ship based on input (WASD or arrow keys)
    if (keys["ArrowLeft"] || keys["a"]) ship.x -= SHIP_SPEED;
    if (keys["ArrowRight"] || keys["d"]) ship.x += SHIP_SPEED;
    if (keys["ArrowUp"] || keys["w"]) ship.y -= SHIP_SPEED;
    if (keys["ArrowDown"] || keys["s"]) ship.y += SHIP_SPEED;

    // Keep ship within bounds
    ship.x = Math.max(ship.size / 2, Math.min(canvas.width - ship.size / 2, ship.x));
    ship.y = Math.max(ship.size / 2, Math.min(canvas.height - ship.size / 2, ship.y));

    // Update asteroids
    for (let i = asteroids.length - 1; i >= 0; i--) {
      const a = asteroids[i];
      a.y += a.speed;
      // Remove off‑screen
      if (a.y - a.radius > canvas.height) {
        asteroids.splice(i, 1);
        score += 10;
        continue;
      }
      // Collision with ship
      const dx = a.x - ship.x;
      const dy = a.y - ship.y;
      const dist = Math.hypot(dx, dy);
      if (dist < a.radius + ship.size / 2) {
        ship.alive = false;
        break;
      }
    }

    // Update fuels
    for (let i = fuels.length - 1; i >= 0; i--) {
      const f = fuels[i];
      f.y += f.speed;
      if (f.y - f.size > canvas.height) {
        fuels.splice(i, 1);
        continue;
      }
      // Collision with ship
      if (
        Math.abs(f.x - ship.x) < (f.size + ship.size) / 2 &&
        Math.abs(f.y - ship.y) < (f.size + ship.size) / 2
      ) {
        ship.fuel = Math.min(100, ship.fuel + FUEL_AMOUNT);
        fuels.splice(i, 1);
        score += 20;
      }
    }

    // Fuel consumption
    ship.fuel -= FUEL_DECREASE_RATE * delta;
    if (ship.fuel <= 0) ship.alive = false;

    // Spawn new asteroids / fuels
    const now = Date.now();
    if (now - lastAsteroidTime > ASTEROID_SPAWN_INTERVAL) {
      spawnAsteroid();
      lastAsteroidTime = now;
    }
    if (now - lastFuelTime > FUEL_SPAWN_INTERVAL) {
      spawnFuel();
      lastFuelTime = now;
    }
  }

  function draw() {
    // Clear
    ctx.fillStyle = "#000";
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Draw ship (triangle pointing up)
    ctx.save();
    ctx.translate(ship.x, ship.y);
    ctx.fillStyle = "#0f0";
    ctx.beginPath();
    ctx.moveTo(0, -ship.size / 2);
    ctx.lineTo(-ship.size / 2, ship.size / 2);
    ctx.lineTo(ship.size / 2, ship.size / 2);
    ctx.closePath();
    ctx.fill();
    ctx.restore();

    // Draw asteroids
    ctx.fillStyle = "#888";
    for (const a of asteroids) {
      ctx.beginPath();
      ctx.arc(a.x, a.y, a.radius, 0, Math.PI * 2);
      ctx.fill();
    }

    // Draw fuel pickups
    ctx.fillStyle = "#ff0";
    for (const f of fuels) {
      ctx.fillRect(f.x - f.size / 2, f.y - f.size / 2, f.size, f.size);
    }

    // UI: fuel & score
    ctx.fillStyle = "#fff";
    ctx.font = "16px sans-serif";
    ctx.fillText(`Fuel: ${Math.max(0, ship.fuel).toFixed(0)}%`, 10, 20);
    ctx.fillText(`Score: ${score}`, 10, 40);

    if (!ship.alive) {
      ctx.fillStyle = "rgba(0,0,0,0.7)";
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = "#f00";
      ctx.font = "48px sans-serif";
      ctx.textAlign = "center";
      ctx.fillText("Game Over", canvas.width / 2, canvas.height / 2);
      ctx.font = "24px sans-serif";
      ctx.fillText(`Score: ${score}`,
        canvas.width / 2,
        canvas.height / 2 + 40
      );
    }
  }

  let lastTime = performance.now();
  function loop(now) {
    const delta = now - lastTime;
    lastTime = now;
    update(delta);
    draw();
    if (ship.alive) requestAnimationFrame(loop);
  }

  requestAnimationFrame(loop);
})();
